	internal static string FetchRandomCallsign_Unit()
	{
		if (Information.IsNothing((object)Callsigns))
		{
			smethod_0();
		}
		return Callsigns[GameGeneral.GlobalRNG.Next(0, Callsigns.Count - 1)];
	}

	internal static string FetchRandomCallsign_Flight_Strike()
