		return Callsigns_Flight_Strike[GameGeneral.GlobalRNG.Next(0, Callsigns_Flight_Strike.Count - 1)] + Conversions.ToString(GameGeneral.GlobalRNG.Next(1, 99));
	}

	internal static string FetchRandomCallsign_Flight_Support()
