	internal static string FetchCallsignBasedOnMissionType(ref Mission theMission)
	{
		if (!Information.IsNothing((object)theMission) && (theMission.MissionClass == Mission._MissionClass.Strike || theMission.MissionClass == Mission._MissionClass.Patrol || theMission.MissionClass == Mission._MissionClass.Mining))
